export const page = String.raw`<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Support desk demo</title><style>
body{font:17px system-ui;max-width:820px;margin:40px auto;padding:0 20px;background:#f4f6fa;color:#183043}textarea{width:100%;box-sizing:border-box;min-height:160px;padding:14px;font:inherit}button,select{font:inherit;padding:9px 16px;margin:8px 8px 8px 0}article{background:white;border:1px solid #ccd6df;border-radius:12px;padding:20px;margin:16px 0}pre{white-space:pre-wrap;font:inherit}progress{width:100%}.badge{background:#fff0c9;padding:12px;border-radius:8px}#error{color:#a11}
</style><h1>Support desk</h1><p class="badge">Demo, no AI model. Deterministic rules and reply templates. Nothing is sent to customers.</p>
<label>Local demo account <select id="account"><option>alice</option><option>bob</option></select></label>
<p>Paste a ticket. Review the summary, category and draft, or cancel while it is running.</p>
<textarea id="ticket">I cannot access my account after changing my password.</textarea><br><button id="start">Prepare draft</button><p id="error"></p><section id="runs"></section>
<script>
let token = ''
let account = 'alice'
let generation = 0
let polling = false
let errorKind = ''
const error = document.getElementById('error')
const start = document.getElementById('start')
const accountPicker = document.getElementById('account')
const runList = document.getElementById('runs')

function clearError() {
    error.textContent = ''
    errorKind = ''
}

function showError(problem, mine) {
    if (mine != generation) return
    error.textContent = problem.message
    errorKind = problem.sessionRenewed ? 'session' : 'request'
}

async function login(mine) {
    const response = await fetch('/demo-session', {
        method: 'POST',
        headers: {'content-type': 'application/json'},
        body: JSON.stringify({account}),
    })
    const data = await response.json()
    if (mine != generation) return
    if (!response.ok || !data.token) throw Error('Could not open the demo session')
    token = data.token
    start.disabled = false
}

async function call(method, args) {
    const mine = generation
    const response = await fetch('/api/' + account + '/' + method, {
        method: args ? 'POST' : 'GET',
        headers: {authorization: 'Bearer ' + token, 'content-type': 'application/json'},
        ...(args ? {body: JSON.stringify({args})} : {}),
    })
    if (mine != generation) return
    if (response.status == 401) {
        await login(mine)
        throw Object.assign(Error('Demo session renewed; try again'), {sessionRenewed: true})
    }
    const data = await response.json()
    if (!data.ok) throw Error(data.error?.message || 'Request failed')
    return data.value
}

function createCard(run) {
    const mine = generation
    const card = document.createElement('article')
    const title = document.createElement('h2')
    title.textContent = run.state + ' — ' + (run.message || 'ticket')
    card.append(title)
    const progress = document.createElement('progress')
    progress.max = 1
    progress.value = run.progress
    card.append(progress)
    if (run.error) {
        const failure = document.createElement('p')
        failure.textContent = 'Could not prepare this draft: ' + run.error
        card.append(failure)
    }
    if (run.result) {
        const text = document.createElement('pre')
        text.textContent = 'Summary: ' + run.result.summary
            + '\n\nCategory: ' + run.result.category
            + '\n\nDraft: ' + run.result.draft
        card.append(text)
    }
    if (run.state == 'running' || run.state == 'queued') {
        const cancel = document.createElement('button')
        cancel.textContent = 'Cancel'
        cancel.onclick = async function cancelDraft() {
            if (mine != generation) return
            try {
                await call('cancelRun', [run.id, 'Cancelled in support desk'])
                if (mine != generation) return
                clearError()
                await refresh()
            } catch (problem) { showError(problem, mine) }
        }
        card.append(cancel)
    }
    return card
}

async function refresh() {
    if (!token || polling) return
    polling = true
    const mine = generation
    try {
        const runs = await call('runs')
        if (mine != generation) return
        runList.replaceChildren(...runs.reverse().map(createCard))
        if (errorKind == 'session') clearError()
    } catch (problem) {
        showError(problem, mine)
    } finally {
        polling = false
    }
}

async function changeAccount() {
    const mine = ++generation
    account = accountPicker.value
    token = ''
    start.disabled = true
    clearError()
    runList.replaceChildren()
    try {
        await login(mine)
        if (mine == generation) await refresh()
    } catch (problem) { showError(problem, mine) }
}

async function prepareDraft() {
    const mine = generation
    clearError()
    try {
        await call('createRun', [{
            requestId: crypto.randomUUID(),
            kind: 'ticket',
            input: {ticket: document.getElementById('ticket').value},
        }])
        if (mine == generation) await refresh()
    } catch (problem) { showError(problem, mine) }
}

accountPicker.onchange = changeAccount
start.onclick = prepareDraft
changeAccount()
setInterval(refresh, 400)
</script></html>`
